import java.util.*;

class Solution {
    public int countDigits(int n) {
        return countDigits(n, 0);
    }

    private int countDigits(int n, int count) {
        if (n == 0) {
            return Math.max(1, count);
        }
        return countDigits(n / 10, count + 1);
    }
}

import java.util.*;

class Solution {
    public int countDigits(int n) {
        int count = 0;
        do {
            count++;
            n /= 10;
        } while (n > 0);
        return count;
    }
}

import java.util.*;

class Solution {
    public int countDigits(int n) {
        if (n < 10) {
            return 1;
        }
        return 1 + countDigits(n - 1);
    }
}

